body.onloadscript:

        	if(Sepoa.request){
	            var tableName = Sepoa.request.TABLE_NAME;
    	        var transactionCode = Sepoa.request.TRANSACTION_CODE;
        	    doQuery(tableName, transactionCode);
        	}

userscript.function:

doServiceAjax('sepoa.svc.admin.IFH_001', 'CONNECTION', 'doQueryData', {
    TABLE_NAME: tableName,
    TRANSACTION_CODE: transactionCode
}, function(so) {
    if (so.status == 1) {
        var soResult = new SepoaFormater(so.result[0]);

        if (soResult.getArrayMap().length < 1) {
            Alert(Sepoa.cache.text.get('MESSAGE.1001')+'</br>'+tableName);
            return;
        }

        var idx = 0;
        var columnIdxMap = {};
        var colArr = [];
        for (var x in soResult.getArrayMap()[0]) {
            if (x == "") continue;
            gridObj.insertColumn(idx, x, 'rotxt', 150, null, 'center', null, null, null);
            columnIdxMap[x] = idx;
            idx++;
        }

        for (var i = 0; i < soResult.getArrayMap().length; i++) {
            var maxRowId = new Date().getTime() + '' + dhx4.newId();
            gridObj.addRow(maxRowId, '', gridObj.getRowsNum());

            for (var column in soResult.getArrayMap()[i]) {
            	if(column == "") continue;
                gridObj.cells(maxRowId, columnIdxMap[column]).setValue(soResult.getArrayMap()[i][column]);
            }
        }

    } else {
        Alert(Sepoa.cache.text.get('MESSAGE.1002'));
        return false;
    }
});
